import torch
from PIL import Image
import numpy as np

class SafeImageFolder(ImageFolder):
    def __getitem__(self, index):
        try:
            return super().__getitem__(index)
        except Exception as e:
            # If loading fails, return a properly normalized random image
            size = 64
            num_channels = 3
            # Generate random image already normalized like ToTensor+Normalize would produce
            # Normalize: (x - mean) / std, with mean=0.5, std=0.5
            # So: (x - 0.5) / 0.5 = 2x - 1, where x is in [0, 1]
            # So we generate random values in roughly [-1, 1] range
            dummy_img = torch.randn(num_channels, size, size) * 2.0
            dummy_label = 0
            return (dummy_img, dummy_label)

dataset = SafeImageFolder(root="data_small/celeba_hq_256",
                         transform=transformer)
